fn apply(r:&Path,g:&Git,t:&T,forward:bool)->Result<()>{check(r,g,t,forward)?;let dest=if forward{"new"}else{"old"};let source=if forward{"old"}else{"new"};let from=if forward{&t.a}else{&t.z};let to=if forward{&t.z}else{&t.a};let mut gone=t.ch.iter().filter(|x|x[dest].is_null()&&!x[source].is_null()).collect::<Vec<_>>();gone.sort_by_key(|x|std::cmp::Reverse(dep(x["path"].as_str().unwrap_or(""))));for x in gone{let p=val(x,"path")?;let s=at(r,g,&p)?;if let S::L(_) = s{if !fits(&s,from,&p)&&!fits(&s,to,&p){return Err(er("leaf changed before deletion"))}util::replace_leaf(&r.join(&p),None)?;}else if !fits(&s,to,&p){return Err(er("deletion path topology changed"))}}let mut dirs=t.ds.iter().filter(|d|d[dest].is_null()).collect::<Vec<_>>();dirs.sort_by_key(|d|std::cmp::Reverse(dep(d["path"].as_str().unwrap_or(""))));for d in dirs{let p=val(d,"path")?;if matches!(at(r,g,&p)?,S::D(_)){util::remove_empty_dir(&r.join(p))?;}}let mut dirs=t.ds.iter().filter(|d|!d[dest].is_null()).collect::<Vec<_>>();dirs.sort_by_key(|d|dep(d["path"].as_str().unwrap_or("")));for d in &dirs{let p=val(d,"path")?;match at(r,g,&p)?{S::N=>util::ensure_dir(&r.join(p),0o700)?,S::D(_)=>{},_=>return Err(er("directory creation blocked by a concurrent leaf"))}}for x in t.ch.iter().filter(|x|!x[dest].is_null()){let p=val(x,"path")?;let s=at(r,g,&p)?;if !fits(&s,from,&p)&&!fits(&s,to,&p){return Err(er("leaf changed before replacement"))}let e:Option<Entry>=serde_json::from_value(x[dest].clone())?;util::replace_leaf(&r.join(&p),stored(g,e.as_ref())?.as_ref())?;}for d in dirs.into_iter().rev(){let p=val(d,"path")?;let mode=mode(&d[dest])?.ok_or_else(||er("directory mode absent"))?;if !matches!(at(r,g,&p)?,S::D(n) if n==mode){util::ensure_dir(&r.join(p),mode)?;}}if forward{symlink_graph(g,&t.a,&t.z,&t.keep)?;}for x in &t.ch{let p=val(x,"path")?;if !fits(&at(r,g,&p)?,to,&p){return Err(er("transaction destination changed before completion"))}}Ok(())}
pub fn recover(r:&Path)->Result<Value>{let l=journal::Lock::take(r,"round")?;recover_locked(r,&l)}fn recover_locked(r:&Path,l:&journal::Lock)->Result<Value>{let mut pending=BTreeMap::<String,Value>::new();let mut used=BTreeSet::new();for q in journal::read(r,"round")?{let e=q.event;match e["t"].as_str(){Some("advance/begin")=>{let id=val(&e,"tx")?;util::ident(&id)?;let round=val(&e,"round")?;util::ident(&round)?;if round.contains('/')||e["ref"]!="refs/heads/main"{return Err(er("transaction round/ref is invalid"))}crate::git::oid(&val(&e,"base")?)?;crate::git::oid(&val(&e,"commit")?)?;if !used.insert(id.clone()){return Err(er("duplicate or reused transaction begin"))}if !pending.is_empty(){return Err(er("overlapping incomplete advances require manual review"))}pending.insert(id,e);},Some("advance/end")|Some("advance/rollback")=>{let id=val(&e,"tx")?;let begin=pending.remove(&id).ok_or_else(||er("orphan or duplicate transaction terminal receipt"))?;if e["round"]!=begin["round"]||e.get("recovered").is_some_and(|v|!v.is_boolean()){return Err(er("transaction terminal receipt does not match its begin"))}},_=>{}}}if pending.len()>1{return Err(er("multiple incomplete advances require manual review"))}let g=Git::open(r)?;let mut jobs=vec![];for(id,e)in pending{let b=val(&e,"base")?;let target=val(&e,"commit")?;let h=g.resolve(&val(&e,"ref")?)?;let fw=if h.as_deref()==Some(&target){true}else if h.as_deref()==Some(&b){false}else{return Err(er("incomplete transaction and externally changed ref; manual review required"))};let t=tx(&g,&e)?;check(r,&g,&t,fw)?;let terminal=json!({"t":if fw{"advance/end"}else{"advance/rollback"},"tx":id,"round":e["round"],"recovered":true});journal::preflight_locked(l,&[terminal])?;jobs.push((id,e,t,fw));}let mut n=0;for(id,e,t,fw)in jobs{apply(r,&g,&t,fw)?;let expected=val(&e,if fw{"commit"}else{"base"})?;g.advance("refs/heads/main",&expected,Some(&expected))?;journal::append_locked(l,json!({"t":if fw{"advance/end"}else{"advance/rollback"},"tx":id,"round":e["round"],"recovered":true}))?;n+=1}Ok(json!({"recovered":n}))}
pub fn advance_verified(r:&Path,round:&str,b:&str,t:&str)->Result<Value>{advance_verified_with_preserve(r,round,b,t,&[])}pub fn advance_verified_with_preserve(r:&Path,round:&str,b:&str,target:&str,preserve:&[String])->Result<Value>{util::ident(round)?;if round.contains('/'){return Err(er("transaction round must be one identity segment"))}let keep=keeps(Some(&json!(preserve)))?;let l=journal::Lock::take(r,"round")?;recover_locked(r,&l)?;let g=Git::open(r)?;let p=plan(r,&g,&g.tree(b)?,&g.tree(target)?,&keep)?;if g.resolve("refs/heads/main")?.as_deref()!=Some(b)||!p.bad.is_empty(){return Err(er(format!("drift rejected advancement: colliding {:?}",p.bad)))}let id=format!("{:x}",Sha256::digest(format!("{round}:{b}:{target}:{}",journal::read(r,"round")?.len())));let e=json!({"t":"advance/begin","tx":id,"round":round,"ref":"refs/heads/main","base":b,"commit":target,"changes":p.ch,"directories":p.ds,"preserve":keep});let t=tx(&g,&e)?;check(r,&g,&t,true)?;journal::preflight_locked(&l,&[e.clone(),json!({"t":"advance/rollback","tx":id,"round":round,"recovered":false})])?;journal::append_locked(&l,e)?;let result=(||->Result<()>{apply(r,&g,&t,true)?;for p in t.a.keys().chain(t.z.keys()).collect::<BTreeSet<_>>(){if t.a.get(p)!=t.z.get(p)&&!preserved(p,&t.keep)&&!fits(&at(r,&g,p)?,&t.z,p){return Err(er("worktree changed before ref compare-and-swap"))}}if g.resolve("refs/heads/main")?.as_deref()!=Some(b){return Err(er("main changed during advancement"))}g.advance("refs/heads/main",target,Some(b))?;Ok(())})();if let Err(e)=result{let back=apply(r,&g,&t,false);if back.is_ok(){journal::append_locked(&l,json!({"t":"advance/rollback","tx":id,"round":round,"recovered":false}))?;}return Err(er(format!("advancement failed: {e}; rollback {}",if back.is_ok(){"complete"}else{"blocked by concurrent change; recovery required"})))}journal::append_locked(&l,json!({"t":"advance/end","tx":id,"round":round,"recovered":false}))?;Ok(json!({"written":t.ch.iter().filter(|x|!x["new"].is_null()).map(|x|x["path"].clone()).collect::<Vec<_>>(),"removed":t.ch.iter().filter(|x|x["new"].is_null()).map(|x|x["path"].clone()).collect::<Vec<_>>(),"skipped":t.keep,"commit":target}))}

pub fn fold(g:&Git,b:&str,cs:&[String])->Result<Value>{for c in std::iter::once(b).chain(cs.iter().map(String::as_str)){crate::git::oid(c)?;if g.resolve(c)?.as_deref()!=Some(c){return Err(Error::new("fold input is not an existing full commit ID"))}}if cs.is_empty(){return Err(Error::new("cannot fold an empty set of worker commits"))}let mut acc=cs[0].clone();let mut steps=0;for (ix,c) in cs.iter().enumerate().skip(1){let(status,out,_)=g.try_run(&["merge-tree","--write-tree","--no-messages","-z",&acc,c],None)?;if status!=0&&status!=1{return Err(Error::new(format!("merge-tree operational failure: exit {status}")))}let mut rows=out.split(|b|*b==0);let tree=std::str::from_utf8(rows.next().ok_or_else(||Error::new("merge-tree returned no tree"))?).map_err(|_|Error::new("merge-tree metadata is not UTF8"))?.trim();crate::git::oid(tree)?;g.tree(tree)?;if status==1{let mut conflicts=BTreeMap::<String,Vec<Value>>::new();for row in rows{if row.is_empty(){continue}let row=std::str::from_utf8(row).map_err(|_|Error::new("conflict metadata not UTF8"))?;let (head,path)=row.split_once('\t').ok_or_else(||Error::new("conflict stage missing path"))?;util::rel(path)?;let h=head.split(' ').collect::<Vec<_>>();if h.len()!=3{return Err(Error::new("conflict stage malformed"))}let mode=u32::from_str_radix(h[0],8).map_err(|_|Error::new("conflict mode malformed"))?;let id=h[1];crate::git::oid(id)?;let stage=h[2].parse::<u8>().map_err(|_|Error::new("conflict stage malformed"))?;if !(1..=3).contains(&stage)||!matches!(mode,0o100644|0o100755|0o120000|0o160000){return Err(Error::new("invalid conflict stage"))}let a=conflicts.entry(path.into()).or_default();if a.iter().any(|x|x["stage"]==stage){return Err(Error::new("duplicate conflict stage"))}a.push(json!({"stage":stage,"mode":mode,"id":id}));}if conflicts.is_empty(){return Err(Error::new("merge-tree failure did not contain genuine conflict stages"))}return Ok(json!({"kind":"conflict","tree":tree,"folded":acc,"rest":&cs[ix..],"conflicts":conflicts.iter().map(|(p,a)|json!({"path":p,"stages":a})).collect::<Vec<_>>(),"steps":steps}));}acc=g.commit_tree(tree,&[acc,c.clone()],"fugue intermediate fold")?;steps+=1;}let tree=String::from_utf8(g.run(&["rev-parse","--verify",&format!("{acc}^{{tree}}")],None)?).map_err(|_|Error::new("tree id decode failed"))?.trim().to_owned();Ok(json!({"kind":"folded","tree":tree,"commit":acc,"steps":steps}))}
#[cfg(test)]mod tests{use super::*;fn fixture()->(tempfile::TempDir,Git,String){let d=tempfile::tempdir().unwrap();assert!(std::process::Command::new("git").args(["init","-q","-b","main"]).arg(d.path()).status().unwrap().success());let g=Git::open(d.path()).unwrap();let mut t=BTreeMap::new();t.insert("a".into(),Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"base").unwrap()});let b=g.commit_tree(&g.put_tree(&t).unwrap(),&[],"base").unwrap();g.advance("refs/heads/main",&b,None).unwrap();util::replace_leaf(&d.path().join("a"),Some(&util::Leaf{mode:0o100644,bytes:b"base".to_vec()})).unwrap();(d,g,b)}#[test]fn drift_guards_and_transaction_preserves_index(){let(d,g,b)=fixture();let mut t=g.tree(&b).unwrap();t.get_mut("a").unwrap().id=g.put_blob(b"new").unwrap();let c=g.commit_tree(&g.put_tree(&t).unwrap(),&[b.clone()],"new").unwrap();util::replace_leaf(&d.path().join("a"),Some(&util::Leaf{mode:0o100644,bytes:b"hand".to_vec()})).unwrap();assert!(advance_verified(d.path(),"r1",&b,&c).is_err());assert_eq!(util::leaf(&d.path().join("a")).unwrap().unwrap().bytes,b"hand");assert_eq!(g.resolve("refs/heads/main").unwrap(),Some(b.clone()));util::replace_leaf(&d.path().join("a"),Some(&util::Leaf{mode:0o100644,bytes:b"base".to_vec()})).unwrap();advance_verified(d.path(),"r1",&b,&c).unwrap();assert_eq!(g.resolve("refs/heads/main").unwrap(),Some(c));assert_eq!(util::leaf(&d.path().join("a")).unwrap().unwrap().bytes,b"new");assert!(!d.path().join(".git/index").exists());}#[test]fn crash_prefix_recovers_to_base(){let(d,g,b)=fixture();let old=g.tree(&b).unwrap()["a"].clone();let new=Entry{kind:"file".into(),mode:0o100644,id:g.put_blob(b"new").unwrap()};let mut target=g.tree(&b).unwrap();target.insert("a".into(),new.clone());let commit=g.commit_tree(&g.put_tree(&target).unwrap(),&[b.clone()],"new").unwrap();let e=json!({"t":"advance/begin","tx":"crash","round":"r1","ref":"refs/heads/main","base":b,"commit":commit,"changes":[{"path":"a","old":old,"new":new}]});journal::append(d.path(),"round",e).unwrap();util::replace_leaf(&d.path().join("a"),Some(&util::Leaf{mode:0o100644,bytes:b"new".to_vec()})).unwrap();recover(d.path()).unwrap();assert_eq!(util::leaf(&d.path().join("a")).unwrap().unwrap().bytes,b"base");}}
